import * as core from "@actions/core";
import { getServiceLogs, listServices, listServiceTasks, } from "./engine.js";
import { findServiceHealthCheck, formatHealthCheck, } from "./healthcheck.js";
import { sleep } from "./utils.js";
/**
 * Monitor deployment rollout
 *
 * This function monitors the deployment of a Docker stack and checks the status
 * of its tasks until all tasks are running or a timeout occurs.
 * It provides feedback on the deployment status and attempts to report any
 * errors encountered after the containers are started.
 *
 * @param settings Deployment settings
 */
export async function monitorDeployment(settings, spec) {
    if (!settings.monitor) {
        core.info("Post-Deployment Monitoring is disabled");
        return;
    }
    core.info(`Monitoring Stack "${settings.stack}" for Post-Deployment Issues`);
    const startTime = new Date();
    const baseInterval = settings.monitorInterval * 1_000;
    const maxInterval = Math.min(baseInterval * 6, settings.monitorTimeout * 1_000);
    let currentInterval = baseInterval;
    const completedServices = new Set();
    let services = [];
    do {
        const elapsed = Date.now() - startTime.getTime();
        if (elapsed >= settings.monitorTimeout * 1_000) {
            // On timeout, report diagnostics for all non-converged services.
            // Prefetch tasks in parallel, then build reports sequentially to
            // avoid interleaving job summary output.
            const pendingOnTimeout = services.filter((s) => !completedServices.has(s.ID));
            const prefetchedTasks = await Promise.all(pendingOnTimeout.map((s) => fetchTasks(s.ID)));
            for (let i = 0; i < pendingOnTimeout.length; i++) {
                const service = pendingOnTimeout[i];
                const name = service.Spec?.Name ?? service.Name ?? service.ID;
                const healthcheck = findServiceHealthCheck(spec, name);
                await buildFailureReport(service.ID, name, startTime, prefetchedTasks[i] ?? undefined, healthcheck);
            }
            const convergedNames = services
                .filter((s) => completedServices.has(s.ID))
                .map((s) => s.Spec?.Name ?? s.Name ?? s.ID);
            const pendingNames = services
                .filter((s) => !completedServices.has(s.ID))
                .map((s) => s.Spec?.Name ?? s.Name ?? s.ID);
            // Job summary table for partial success
            core.summary.addHeading("Deployment timeout summary", 2);
            core.summary.addTable([
                [
                    { data: "Service", header: true },
                    { data: "Status", header: true },
                ],
                ...convergedNames.map((n) => [{ data: n }, { data: "Converged" }]),
                ...pendingNames.map((n) => [{ data: n }, { data: "Pending" }]),
            ]);
            await publishSummary();
            if (convergedNames.length > 0) {
                core.info(`Services converged: ${convergedNames.join(", ")}`);
            }
            if (pendingNames.length > 0) {
                // Not an annotation: each pending service already emitted one via
                // `buildFailureReport`, and the thrown message below reports the
                // counts and is annotated by `setFailed`.
                core.info(`Services not converged: ${pendingNames.join(", ")}`);
            }
            throw new Error(`Deployment timed out after ${settings.monitorTimeout}s: ` +
                `${completedServices.size}/${services.length} services converged. ` +
                `See the per-service failure reports above for why the remaining ` +
                `services did not become healthy, or raise the "monitor-timeout" ` +
                `input if they simply need more time.`);
        }
        services = await listServices({ labels: { "com.docker.stack.namespace": settings.stack } }, true);
        core.debug(`Waiting for services to finish updating: ` +
            `${completedServices.size}/${services.length}`);
        const previousSize = completedServices.size;
        // Check all pending services in parallel: fetch tasks concurrently
        // instead of sequentially, which matters most when many services are
        // still updating and each `docker service ps` call takes ~100-500ms.
        const pendingServices = services.filter((s) => !completedServices.has(s.ID));
        const checks = await Promise.all(pendingServices.map(async (service) => {
            let complete;
            try {
                complete = isServiceUpdateComplete(service);
            }
            catch (error) {
                return [service, { kind: "update_failed", error }];
            }
            if (complete) {
                return [service, { kind: "complete" }];
            }
            // If the service appears to be "updating" but all tasks are in a
            // terminal failure state, it will never recover — fail early instead
            // of waiting for the full timeout.
            const tasks = await fetchTasks(service.ID);
            if (tasks && isServiceStuck(tasks)) {
                return [service, { kind: "stuck", tasks }];
            }
            return [service, { kind: "pending" }];
        }));
        // Process completions first
        for (const [service, result] of checks) {
            if (result.kind === "complete") {
                const name = service.Spec?.Name ?? service.Name ?? service.ID;
                core.info(`Service "${name}" has been deployed successfully`);
                completedServices.add(service.ID);
            }
        }
        const failures = checks.filter((entry) => entry[1].kind === "stuck" || entry[1].kind === "update_failed");
        if (failures.length > 0) {
            for (const [service, result] of failures) {
                const name = service.Spec?.Name ?? service.Name ?? service.ID;
                const healthcheck = findServiceHealthCheck(spec, name);
                if (result.kind === "stuck") {
                    await buildFailureReport(service.ID, name, startTime, result.tasks, healthcheck);
                }
                else {
                    await buildFailureReport(service.ID, name, startTime, undefined, healthcheck);
                    // A full service inspect dump is a debug aid, not a headline, and it
                    // is long enough to crowd out the annotation that names the cause.
                    // Guarded so the payload is not serialized when it will be dropped.
                    if (core.isDebug()) {
                        core.debug(`Service Details:\n${JSON.stringify(service, null, 2)}`);
                    }
                }
            }
            const [firstService, firstResult] = failures[0];
            const firstName = firstService.Spec?.Name ?? firstService.Name ?? firstService.ID;
            if (firstResult.kind === "stuck") {
                throw new Error(`Service "${firstName}" failed: all tasks are in a failed state`);
            }
            throw firstResult.error;
        }
        // Reset interval if progress was made, otherwise grow with backoff
        if (completedServices.size > previousSize) {
            currentInterval = baseInterval;
        }
        else {
            currentInterval = Math.min(currentInterval * 1.5, maxInterval);
        }
        if (completedServices.size < services.length) {
            await sleep(currentInterval);
        }
    } while (completedServices.size < services.length);
    core.info("All services have been deployed successfully");
}
/**
 * Check if a Docker service is complete.
 *
 * This function checks whether a Docker service is complete by examining its
 * update status and compares the number of running and desired tasks.
 *
 * @param service Service to check
 * @returns True if the service is complete, false otherwise
 */
export function isServiceUpdateComplete(service) {
    const name = service.Spec?.Name ?? service.Name;
    core.debug(`Checking update status of service ${name}`);
    // Handle missing UpdateStatus
    if (!service.UpdateStatus) {
        if (isServiceRunning(service)) {
            core.info(`Service "${name}" is still running and did not require an update`);
            return true;
        }
        else {
            core.info(`Service "${name}" is still updating`);
            return false;
        }
    }
    // If UpdateStatus exists but State is missing, treat it as "updating"
    // This handles race conditions where service hasn't fully started yet
    const updateStatus = service.UpdateStatus?.State ?? "updating";
    if (updateStatus === "completed") {
        core.info(`Update of service "${name}" is complete`);
        return true;
    }
    if (updateStatus === "updating") {
        core.info(`Update of service "${name}" is still in progress`);
        return false;
    }
    const reason = resolveFailureReason(updateStatus, service.UpdateStatus?.Message);
    throw new Error(`Update of service "${name}" failed: ${reason}`, {
        cause: service.UpdateStatus,
    });
}
/**
 * Check if a Swarm Service is running.
 *
 * The Docker API exposes the number of running and desired tasks for a running
 * service. If these numbers are equal, the service has converged and is running
 * as expected; for our case, this means that the service has either been
 * updated or no update was required.
 *
 * @param service Service to check
 * @returns True if the service is running, false otherwise
 */
export function isServiceRunning(service) {
    const name = service.Spec?.Name ?? service.ID;
    core.debug(`Checking if service "${name}" is currently running`);
    if (service.Replicas) {
        // The Replicas field is formatted as "running/desired", but Docker appends
        // a human-readable suffix such as "1/1 (max 1 per node)" when
        // deploy.placement.max_replicas_per_node is set. Parse the leading integer
        // from each side so the suffix doesn't break the comparison (see #137).
        const [runningStr, desiredStr] = service.Replicas.split("/", 2);
        const running = Number.parseInt(runningStr ?? "", 10);
        const desired = Number.parseInt(desiredStr ?? "", 10);
        if (!Number.isNaN(running) &&
            !Number.isNaN(desired) &&
            running === desired) {
            core.debug(`Service "${name}" is running (${running}/${desired} replicas)`);
            return true;
        }
        core.debug(`Service "${name}" is only partially running: ` +
            `${running}/${desired} tasks running`);
        return false;
    }
    core.debug(`Service "${name}" is not running`);
    return false;
}
async function fetchTasks(serviceId) {
    try {
        return await listServiceTasks(serviceId);
    }
    catch {
        return null;
    }
}
/**
 * Check if all tasks are in terminal failure states.
 *
 * When a service has tasks but every task has failed or been rejected
 * (and none are running, pending, or being prepared), the service will
 * never recover on its own.
 */
export function isServiceStuck(tasks) {
    if (tasks.length === 0) {
        return false;
    }
    return tasks.every((t) => t.CurrentState.startsWith("Failed") ||
        t.CurrentState.startsWith("Rejected"));
}
/**
 * Resolve the failure reason for a service update
 *
 * The failure reason is determined by the state of the service update.
 * The state can be one of the following:
 * - "paused"
 * - "rollback_started"
 * - "rollback_completed"
 * - "rollback_paused"
 * - "unknown"
 *
 * The function returns a human-readable string describing the failure reason.
 *
 * @param state The state of the service update
 * @param message Optional message providing additional context
 * @returns A human-readable string describing the failure reason
 */
function resolveFailureReason(state, message) {
    const reason = {
        paused: "Service is paused",
        rollback_started: "Service failed to update and is being rolled back",
        rollback_completed: "Service failed to update and was rolled back",
        rollback_paused: "Service is paused and is being rolled back",
        unknown: `Service update status '${state}' is unknown`,
    }[state] ?? "Unknown failure reason";
    return reason + (message ? `: ${message}` : "");
}
/**
 * Build a structured diagnostic report for a failed service update.
 */
/**
 * Publish the buffered job summary to the run page
 *
 * `@actions/core` buffers summary content and only writes it to
 * `$GITHUB_STEP_SUMMARY` when this is called, so anything added without it is
 * silently discarded. The runner masks registered secrets in summaries, the
 * same as it does in the log, so no redaction of our own is required here.
 *
 * Failures are reported rather than thrown: callers raise the actual
 * deployment error immediately after building a report, and that error is far
 * more useful than one about writing a summary.
 */
async function publishSummary() {
    try {
        await core.summary.write();
    }
    catch (cause) {
        const message = cause instanceof Error ? cause.message : String(cause);
        core.warning(`Failed to publish the job summary: ${message}`);
    }
}
export async function buildFailureReport(serviceId, serviceName, startTime, prefetchedTasks, healthcheck) {
    const tasks = prefetchedTasks ?? (await fetchTasks(serviceId));
    if (!tasks) {
        core.error(`Failed to fetch task details for service "${serviceName}"`);
        return;
    }
    if (tasks.length === 0) {
        core.error(`No task information available for service "${serviceName}"`);
        return;
    }
    const failedTasks = tasks.filter((t) => t.Error && t.DesiredState !== "Running");
    const latestFailedTask = failedTasks[0];
    const errorResult = latestFailedTask
        ? categorizeTaskError(latestFailedTask.Error)
        : undefined;
    const headline = errorResult?.headline;
    if (headline) {
        core.error(`Service "${serviceName}" failed to deploy: ${headline}`);
    }
    else {
        core.error(`Service "${serviceName}" failed to deploy (no task error details available)`);
    }
    if (errorResult?.category === "health_check" && healthcheck) {
        core.info(`Health check configuration for service "${serviceName}":\n` +
            formatHealthCheck(healthcheck));
    }
    const history = tasks
        .map((t) => {
        const error = t.Error ? ` "${t.Error}"` : "";
        return `  ${t.Name}  ${t.DesiredState.padEnd(10)}  ${t.CurrentState}${error}  (node: ${t.Node})`;
    })
        .join("\n");
    core.info(`Task history for service "${serviceName}":\n${history}`);
    let logs;
    try {
        logs = await getServiceLogs(serviceId, { since: startTime, tail: 50 });
    }
    catch {
        core.warning(`Failed to fetch container logs for service "${serviceName}"`);
        logs = [];
    }
    const formattedLogs = logs.map((entry) => {
        const ts = entry.timestamp?.toISOString() ?? "<no timestamp>";
        return `${ts}  ${entry.message}`;
    });
    if (formattedLogs.length === 0) {
        core.info(`No container logs available for service "${serviceName}" (container may not have started)`);
    }
    else {
        const logOutput = formattedLogs.map((l) => `  ${l}`).join("\n");
        core.setOutput("service-logs", logOutput);
        core.info(`Container logs for service "${serviceName}":\n${logOutput}`);
    }
    // Job summary
    core.summary.addHeading(`Deployment failure: ${serviceName}`, 2);
    if (headline) {
        core.summary.addRaw(`**Root cause:** ${headline}`, true);
    }
    if (errorResult?.category === "health_check" && healthcheck) {
        core.summary.addHeading("Health check configuration", 3);
        core.summary.addCodeBlock(formatHealthCheck(healthcheck));
    }
    core.summary.addHeading("Task history", 3);
    core.summary.addTable([
        [
            { data: "Task", header: true },
            { data: "State", header: true },
            { data: "Current State", header: true },
            { data: "Error", header: true },
            { data: "Node", header: true },
        ],
        ...tasks.map((t) => [
            { data: t.Name },
            { data: t.DesiredState },
            { data: t.CurrentState },
            { data: t.Error || "-" },
            { data: t.Node },
        ]),
    ]);
    if (formattedLogs.length > 0) {
        core.summary.addHeading("Container logs", 3);
        core.summary.addCodeBlock(formattedLogs.join("\n"));
    }
    else {
        core.summary.addRaw("_No container logs available (container may not have started)_", true);
    }
    await publishSummary();
}
const errorPatterns = [
    {
        test: (e) => /No such image|manifest unknown|manifest not found|pull access denied|unauthorized/.test(e),
        category: "image_pull",
        headline: (e) => `Image could not be pulled: ${e}`,
    },
    {
        test: (e) => /non-zero exit \(137\)/.test(e),
        category: "oom_kill",
        headline: () => "Container killed (likely OOM): exit code 137",
    },
    {
        test: (e) => /non-zero exit \((\d+)\)/.test(e),
        category: "container_crash",
        headline: (e) => {
            const code = e.match(/non-zero exit \((\d+)\)/)?.[1] ?? "?";
            return `Container exited with code ${code}`;
        },
    },
    {
        test: (e) => /unhealthy container/.test(e),
        category: "health_check",
        headline: () => "Container failed health check",
    },
    {
        test: (e) => /no suitable node/.test(e),
        category: "scheduling",
        headline: (e) => `No node available to run this task: ${e}`,
    },
    {
        test: (e) => /starting container failed|OCI runtime create failed/.test(e) &&
            !/exec format error|permission denied|no such file or directory/.test(e),
        category: "startup_failure",
        headline: (e) => `Container failed to start: ${e}`,
    },
    {
        test: (e) => /exec format error|(?:^|\W)permission denied|no such file or directory/.test(e),
        category: "entrypoint",
        headline: (e) => `Container entrypoint failed: ${e}`,
    },
    {
        test: (e) => /failed to allocate network IP|Address already in use|missing network attachments/.test(e),
        category: "network",
        headline: (e) => `Network allocation failed: ${e}`,
    },
    {
        test: (e) => /invalid bind mount source|no space left on device/.test(e),
        category: "volume",
        headline: (e) => `Volume or mount failed: ${e}`,
    },
    {
        test: (e) => /secret reference|config reference|(?:secret|config)\S*\s+not found/.test(e),
        category: "config",
        headline: (e) => `Secret or config reference invalid: ${e}`,
    },
    {
        test: (e) => /dependency not ready/.test(e),
        category: "dependency",
        headline: () => "Task dependencies not yet available",
    },
    {
        test: (e) => /host-mode port already in use/.test(e),
        category: "port_conflict",
        headline: (e) => `Host port already in use: ${e}`,
    },
];
export function categorizeTaskError(error) {
    if (!error) {
        return { category: "unknown", headline: "Unknown error" };
    }
    for (const pattern of errorPatterns) {
        if (pattern.test(error)) {
            return {
                category: pattern.category,
                headline: pattern.headline(error),
            };
        }
    }
    return { category: "unknown", headline: error };
}
